// Test suite for the Go PQCrypt reference. Mirrors python/test_pqcrypt.py
// in coverage and consumes the same KAT vectors generated by
// pqcrypt/conformance/scripts/generate.py.
//
// Run from this directory:
//
//	go test ./...
package pqcrypt

import (
	"encoding/hex"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"testing"
)

const katDir = "../conformance/vectors"

// ---------------------------------------------------------------------------
// Self-contained round-trip
// ---------------------------------------------------------------------------

func TestRoundtripAESGCM(t *testing.T) {
	priv, pub, err := GenerateKeypair(SuiteMLKEM1024AESGCM)
	if err != nil {
		t.Fatal(err)
	}
	pt := []byte("hello world from Go")
	env, err := Encrypt(pt, pub, SuiteMLKEM1024AESGCM, nil, 0, 0)
	if err != nil {
		t.Fatal(err)
	}
	got, err := Decrypt(env, priv, nil)
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != string(pt) {
		t.Fatalf("plaintext mismatch: got %q want %q", got, pt)
	}
}

