func TestADBindingWrongAD(t *testing.T) {
	priv, pub, err := GenerateKeypair(SuiteMLKEM1024AESGCM)
	if err != nil {
		t.Fatal(err)
	}
	ad := []byte{1, 2, 3, 4, 5, 6, 7, 8}
	env, err := Encrypt([]byte("x"), pub, SuiteMLKEM1024AESGCM, ad, 0, 0)
	if err != nil {
		t.Fatal(err)
	}
	wrong := append([]byte(nil), ad...)
	wrong[0] ^= 0x01
	if _, err := Decrypt(env, priv, wrong); !errors.Is(err, ErrDecrypt) {
		t.Fatalf("expected ErrDecrypt, got %v", err)
	}
}

func TestUnknownVariantRejected(t *testing.T) {
	priv, pub, err := GenerateKeypair(SuiteMLKEM1024AESGCM)
	if err != nil {
		t.Fatal(err)
	}
	env, err := Encrypt([]byte("x"), pub, SuiteMLKEM1024AESGCM, nil, 0, 0)
	if err != nil {
		t.Fatal(err)
	}
	for _, v := range []byte{0x00, 0x01, 0x02, 0x03, 0x05, 0x10, 0x7F, 0x80, 0xFE, 0xFF} {
		envBad := append([]byte(nil), env...)
		envBad[variantOffset] = v
		if _, err := Decrypt(envBad, priv, nil); !errors.Is(err, ErrUnknownVariant) {
			t.Errorf("variant 0x%02x: expected ErrUnknownVariant, got %v", v, err)
		}
	}
}

