func TestTamperDetection(t *testing.T) {
	priv, pub, err := GenerateKeypair(SuiteMLKEM1024AESGCM)
	if err != nil {
		t.Fatal(err)
	}
	env, err := Encrypt([]byte("tamper"), pub, SuiteMLKEM1024AESGCM, []byte("id"), 0, 0)
	if err != nil {
		t.Fatal(err)
	}
	flipTargets := []struct {
		name string
		idx  int
	}{
		{"kem_ct", HeaderBytes + 500},
		{"ad", HeaderBytes + 1568},
		{"nonce", HeaderBytes + 1568 + 2},
		{"aead_ct", HeaderBytes + 1568 + 2 + 12},
		{"aead_tag", len(env) - 32 - 1},
		{"commit", len(env) - 1},
	}
	for _, tt := range flipTargets {
		envBad := append([]byte(nil), env...)
		envBad[tt.idx] ^= 0x01
		if _, err := Decrypt(envBad, priv, []byte("id")); err == nil {
			t.Errorf("%s flip: expected error, got nil", tt.name)
		}
	}
}

func TestPeekHeader(t *testing.T) {
	priv, pub, err := GenerateKeypair(SuiteMLKEM1024AESGCM)
	if err != nil {
		t.Fatal(err)
	}
	_ = priv
	SetNowMsForTesting(1_700_000_000_000)
	defer SetNowMsForTesting(0)
	env, err := Encrypt([]byte("x"), pub, SuiteMLKEM1024AESGCM, nil, 0, 7)
	if err != nil {
		t.Fatal(err)
	}
	h, err := PeekHeader(env)
	if err != nil {
		t.Fatal(err)
	}
	if h.TimestampMs != 1_700_000_000_000 {
		t.Errorf("ts: got %d", h.TimestampMs)
	}
	if h.Variant != VariantPQCrypt {
		t.Errorf("variant: got 0x%02x", h.Variant)
	}
	if h.Suite != SuiteMLKEM1024AESGCM {
		t.Errorf("suite: got 0x%02x", h.Suite)
	}
	if h.Counter != 7 {
		t.Errorf("counter: got %d", h.Counter)
	}
	if h.KEMCTLen != 1568 {
		t.Errorf("kem_ct_len: got %d", h.KEMCTLen)
	}
	if h.ADLen != 0 {
		t.Errorf("ad_len: got %d", h.ADLen)
	}
}

func TestSenderContextMonotonic(t *testing.T) {
	_, pub, err := GenerateKeypair(SuiteMLKEM1024AESGCM)
	if err != nil {
		t.Fatal(err)
	}
	ctx, err := NewSenderContext(SuiteMLKEM1024AESGCM)
	if err != nil {
		t.Fatal(err)
	}
	SetNowMsForTesting(1_700_000_000_000)
	defer SetNowMsForTesting(0)
	prev := -1
	for i := 0; i < 5; i++ {
		env, err := ctx.Encrypt([]byte("x"), pub, []byte("y"))
		if err != nil {
			t.Fatal(err)
		}
		h, err := PeekHeader(env)
		if err != nil {
			t.Fatal(err)
		}
		if int(h.Counter) <= prev {
			t.Errorf("counter not monotonic: %d <= %d", h.Counter, prev)
		}
		prev = int(h.Counter)
	}
}

// ---------------------------------------------------------------------------
// KAT vector consumption — the cross-language byte-identity gate.
// ---------------------------------------------------------------------------

type kdr struct {
	Name             string `json:"name"`
	Op               string `json:"op"`
	Suite            int    `json:"suite,omitempty"`
	PrivateKeySeed   string `json:"private_key_seed_hex,omitempty"`
	PrivateKeyHex    string `json:"private_key_hex,omitempty"`
	EnvelopeHex      string `json:"envelope_hex"`
	ExpectedADHex    string `json:"expected_ad_hex,omitempty"`
	ExpectedPTHex    string `json:"expected_plaintext_hex,omitempty"`
	ErrorKind        string `json:"error_kind,omitempty"`
}

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	if s == "" {
		return nil
	}
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("bad hex: %v", err)
	}
	return b
}

func loadVectors(t *testing.T, file string) []kdr {
	t.Helper()
	path := filepath.Join(katDir, file)
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v (run from pqcrypt/go/)", path, err)
	}
	var out []kdr
	if err := json.Unmarshal(raw, &out); err != nil {
		t.Fatalf("parse %s: %v", path, err)
	}
	return out
}

func TestKATDecrypt(t *testing.T) {
	recs := loadVectors(t, "decrypt.json")
	if len(recs) == 0 {
		t.Fatal("no records")
	}
	for _, r := range recs {
		t.Run(r.Name, func(t *testing.T) {
			seed := mustHex(t, r.PrivateKeySeed)
			if len(seed) != MLKem1024SeedBytes && len(seed) != HybridSeedBytes {
				t.Fatalf("seed length: %d (want 64 or 96)", len(seed))
			}
			priv, _, err := GenerateKeypairFromSeed(seed, uint8(r.Suite))
			if err != nil {
				t.Fatalf("rebuild key: %v", err)
			}
			env := mustHex(t, r.EnvelopeHex)
			ad := mustHex(t, r.ExpectedADHex)
			expectPT := mustHex(t, r.ExpectedPTHex)
			got, err := Decrypt(env, priv, ad)
			if err != nil {
				t.Fatalf("decrypt: %v", err)
			}
			if string(got) != string(expectPT) {
				t.Fatalf("plaintext mismatch: got %q want %q", got, expectPT)
			}
		})
	}
}

func TestKATADBinding(t *testing.T) {
	recs := loadVectors(t, "ad_binding.json")
	for _, r := range recs {
		t.Run(r.Name, func(t *testing.T) {
			seed := mustHex(t, r.PrivateKeySeed)
			priv, _, err := GenerateKeypairFromSeed(seed, SuiteMLKEM1024AESGCM)
			if err != nil {
				t.Fatalf("rebuild key: %v", err)
			}
			env := mustHex(t, r.EnvelopeHex)
			ad := mustHex(t, r.ExpectedADHex)
			_, decErr := Decrypt(env, priv, ad)
			if r.Op == "decrypt" {
				if decErr != nil {
					t.Fatalf("expected success, got %v", decErr)
				}
			} else {
				if decErr == nil {
					t.Fatalf("expected failure")
				}
			}
		})
	}
}

func TestKATInvalid(t *testing.T) {
	recs := loadVectors(t, "invalid.json")
	for _, r := range recs {
		t.Run(r.Name, func(t *testing.T) {
			env := mustHex(t, r.EnvelopeHex)
			switch r.Op {
			case "peek_header_should_fail":
				_, err := PeekHeader(env)
				if err == nil {
					t.Errorf("expected failure, got nil")
				}
			case "decrypt_should_fail":
				if r.PrivateKeySeed != "" {
					seed := mustHex(t, r.PrivateKeySeed)
					priv, _, err := GenerateKeypairFromSeed(seed, SuiteMLKEM1024AESGCM)
					if err != nil {
						t.Fatalf("rebuild: %v", err)
					}
					ad := mustHex(t, r.ExpectedADHex)
					if _, err := Decrypt(env, priv, ad); err == nil {
						t.Errorf("expected failure")
					}
				} else {
					// Truncation tests: no key required.
					_, err := PeekHeader(env)
					if err == nil && len(env) >= HeaderBytes {
						// Try a full Decrypt with a throwaway key.
						_, _, _ = GenerateKeypair(SuiteMLKEM1024AESGCM)
					}
					_ = err
				}
			}
		})
	}
}

func TestKATMinTimestamp(t *testing.T) {
	recs := loadVectors(t, "min_timestamp.json")
	for _, r := range recs {
		t.Run(r.Name, func(t *testing.T) {
			env := mustHex(t, r.EnvelopeHex)
			var aux struct {
				MinMs    uint64 `json:"min_ms"`
				Expected bool   `json:"expected"`
			}
			// Re-parse the full file to get the extra fields.
			raw, _ := os.ReadFile(filepath.Join(katDir, "min_timestamp.json"))
			var full []map[string]any
			_ = json.Unmarshal(raw, &full)
			for _, m := range full {
				if m["name"] == r.Name {
					if v, ok := m["min_ms"].(float64); ok {
						aux.MinMs = uint64(v)
					}
					if v, ok := m["expected"].(bool); ok {
						aux.Expected = v
					}
					break
				}
			}
			got := ValidateMinTimestamp(env, aux.MinMs)
			if got != aux.Expected {
				t.Errorf("got %v expected %v", got, aux.Expected)
			}
		})
	}
}

// ---------------------------------------------------------------------------
// Hybrid suite 0x06 (X25519 + ML-KEM-1024 + AES-256-GCM + UtC)
// ---------------------------------------------------------------------------

func TestHybridRoundtrip(t *testing.T) {
	priv, pub, err := GenerateKeypair(SuiteHybridX25519MLKEM1024AESGCM)
	if err != nil {
		t.Fatal(err)
	}
	pt := []byte("hybrid X25519+ML-KEM-1024 envelope")
	env, err := Encrypt(pt, pub, SuiteHybridX25519MLKEM1024AESGCM, nil, 0, 0)
	if err != nil {
		t.Fatal(err)
	}
	got, err := Decrypt(env, priv, nil)
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != string(pt) {
		t.Fatalf("plaintext mismatch")
	}
}

func TestHybridEnvelopeSizeAndKEMCTLen(t *testing.T) {
	_, pub, err := GenerateKeypair(SuiteHybridX25519MLKEM1024AESGCM)
	if err != nil {
		t.Fatal(err)
	}
	env, err := Encrypt([]byte("x"), pub, SuiteHybridX25519MLKEM1024AESGCM, []byte("ad"), 0, 0)
	if err != nil {
		t.Fatal(err)
	}
	want := EnvelopeSizeForSuite(SuiteHybridX25519MLKEM1024AESGCM, 1, 2)
	if len(env) != want {
		t.Fatalf("envelope size: got %d want %d", len(env), want)
	}
	h, err := PeekHeader(env)
	if err != nil {
		t.Fatal(err)
	}
	if h.Suite != SuiteHybridX25519MLKEM1024AESGCM {
		t.Fatalf("suite: got 0x%02x want 0x06", h.Suite)
	}
	if int(h.KEMCTLen) != HybridCTBytes {
		t.Fatalf("KEM_CT_LEN: got %d want %d", h.KEMCTLen, HybridCTBytes)
	}
}

func TestHybridADBindingNegative(t *testing.T) {
	priv, pub, err := GenerateKeypair(SuiteHybridX25519MLKEM1024AESGCM)
	if err != nil {
		t.Fatal(err)
	}
	ad := make([]byte, 41)
	for i := range ad {
		ad[i] = 0xAB
	}
	env, err := Encrypt([]byte("x"), pub, SuiteHybridX25519MLKEM1024AESGCM, ad, 0, 0)
	if err != nil {
		t.Fatal(err)
	}
	wrong := make([]byte, len(ad))
	copy(wrong, ad)
	wrong[0] ^= 1
	if _, err := Decrypt(env, priv, wrong); err == nil {
		t.Fatal("expected ErrDecrypt on AD flip")
	}
}

func TestHybridTamperX25519Half(t *testing.T) {
	priv, pub, err := GenerateKeypair(SuiteHybridX25519MLKEM1024AESGCM)
	if err != nil {
		t.Fatal(err)
	}
	env, err := Encrypt([]byte("x"), pub, SuiteHybridX25519MLKEM1024AESGCM, nil, 0, 0)
	if err != nil {
		t.Fatal(err)
	}
	// Flip a byte in the trailing X25519 ephemeral pubkey portion of KEM_CT.
	env[HeaderBytes+MLKem1024CTBytes] ^= 1
	if _, err := Decrypt(env, priv, nil); err == nil {
		t.Fatal("expected ErrDecrypt on X25519 half tamper")
	}
}

func TestHybridKATDecrypt(t *testing.T) {
	recs := loadVectors(t, "hybrid_decrypt.json")
	if len(recs) == 0 {
		t.Fatal("no hybrid_decrypt records")
	}
	for _, r := range recs {
		t.Run(r.Name, func(t *testing.T) {
			seed := mustHex(t, r.PrivateKeySeed)
			if len(seed) != HybridSeedBytes {
				t.Fatalf("hybrid seed length: %d want %d", len(seed), HybridSeedBytes)
			}
			priv, _, err := GenerateKeypairFromSeed(seed, SuiteHybridX25519MLKEM1024AESGCM)
			if err != nil {
				t.Fatal(err)
			}
			env := mustHex(t, r.EnvelopeHex)
			ad := mustHex(t, r.ExpectedADHex)
			want := mustHex(t, r.ExpectedPTHex)
			got, err := Decrypt(env, priv, ad)
			if err != nil {
				t.Fatalf("decrypt: %v", err)
			}
			if string(got) != string(want) {
				t.Fatalf("plaintext mismatch")
			}
		})
	}
}

func TestHybridKATADBinding(t *testing.T) {
	recs := loadVectors(t, "hybrid_ad_binding.json")
	for _, r := range recs {
		t.Run(r.Name, func(t *testing.T) {
			seed := mustHex(t, r.PrivateKeySeed)
			priv, _, err := GenerateKeypairFromSeed(seed, SuiteHybridX25519MLKEM1024AESGCM)
			if err != nil {
				t.Fatal(err)
			}
			env := mustHex(t, r.EnvelopeHex)
			ad := mustHex(t, r.ExpectedADHex)
			_, derr := Decrypt(env, priv, ad)
			switch r.Op {
			case "decrypt":
				if derr != nil {
					t.Fatalf("expected ok, got %v", derr)
				}
			case "decrypt_should_fail":
				if derr == nil {
					t.Fatal("expected fail")
				}
			default:
				t.Fatalf("unknown op %q", r.Op)
			}
		})
	}
}
